ANNOTATIONS = [
    (42, 'after_block', r'''文件级：输入补全的总枢纽，PromptInput 的大脑。六条正则共用一套 Unicode 感知字符类——\p{L}/\p{N}/\p{M} 让 CJK 文件名、组合字符（macOS NFD 音标）都能进补全 token。AT_TOKEN_HEAD_RE 的 u 标志不是装饰：没有它 CJK 路径会被按 UTF-16 码元切断。'''),
    (49, 'after', r'''isPathMetadata：补全项的元数据守卫，区分目录（补全后加 / 继续下钻）与文件（加空格收尾）。'''),
    (74, 'after', r'''getPreservedSelection：列表刷新时按 item.id 找回原来的选中项，找不到回 0——用户不会因为补全结果更新就丢掉光标位置。'''),
    (80, 'after', r'''buildResumeInputFromSuggestion：/resume 补全优先带 sessionId（精确恢复），退化到标题文本（模糊匹配）。'''),
    (107, 'after', r'''Props 是受控双轨设计：suggestions 状态放在父组件，本 hook 只通过 setSuggestionsState 函数式更新改它——PromptInput 的多个消费方（footer 计数、ghost text、overlay）共享同一份状态。'''),
    (116, 'after', r'''UseTypeaheadResult 的 inlineGhostText 是异步产物（bash 历史补全要等），suggestions 是同步产物。'''),
    (135, 'after', r'''extractSearchToken：从补全 token 剥出搜索词。quoted 形态砍掉 @" 前缀和尾引号；裸 @ 砍一个字符。'''),
    (173, 'after', r'''formatReplacementValue：bash 模式下不加 @（shell 里 @ 没有语义），prompt 模式加；有空格的路径才引号化，已引号的原样保留。isComplete 决定尾随空格——补全完了加空格让用户直接继续打下一个词。'''),
    (195, 'after', r'''applyShellSuggestion：shell 补全按 completionType 决定替换文本——变量补 $ 前缀、命令补尾随空格、其他原样。光标落在替换文本末尾。'''),
    (205, 'after', r'''applyTriggerSuggestion：@队友 / #频道 的通用触发替换。从光标前文本匹配触发正则，用 m[1] 的长度跳过前导空白定位替换点。'''),
    (224, 'after', r'''generateBashSuggestions：模块级单例 AbortController——新查询直接 abort 上一次（shell 补全要起子进程，慢且贵）。失败静默返回空数组 + 记遥测事件：补全坏了不该打断输入，但要知道它坏了。'''),
    (252, 'after', r'''applyDirectorySuggestion：永远补 @ 前缀——整个 token（含已有的 @）被替换掉，这是「@ 路径补全」与「普通路径补全」的分界。'''),
    (325, 'after', r'''extractCompletionToken 三条路径：① 引号形态（@"my file with spaces"，光标后可继续吃到闭引号）② @ token 快路径（lastIndexOf 避免 $ 锚扫描整串）③ 通用 $ 锚。光标落在 token 中部时向后扩展到空白——补全要覆盖整个词不只是光标左边的部分。'''),
    (348, 'after', r'''hasCommandWithArguments：区分「用户打完命令在打参数」与「退回去改命令名」——后者（不在行尾、有空格、不以空格结尾）不该显示命令补全，否则会把参数里的词当命令名匹配。'''),
    (371, 'after', r'''useTypeahead 签名：suggestionsState 解构后直接当受控值用，写入全走父级 setter。'''),
    (385, 'after', r'''allCommandsMaxWidth 从**全部**可见命令算（不是过滤结果）——补全列表过滤时列宽不变，消除布局跳动。+6 = 1 个 / 前缀 + 5 个 padding。'''),
    (414, 'after', r'''syncPromptGhostText 用同步 useMemo 而不是 useState+useEffect：effect 在渲染后跑，会有一帧幽灵文本闪烁。中段命令补全（help me /com）的 ghost text 是纯函数式的，同步算得出来。'''),
    (438, 'after', r'''六个 ref 是「陈旧结果丢弃」模式的标准配置：每个异步源（文件/路径/bash 历史/slack）配一个 latest ref，异步返回后比对，不等就丢。cursorOffsetRef 单独存在是为了光标移动不触发重取——只有搜索词变化才算。'''),
    (450, 'after', r'''clearSuggestions 清四件套：suggestions、type、列宽、ghost text。'''),
    (478, 'after', r'''fetchFileSuggestions：generateUnifiedSuggestions 合并文件/MCP 资源/subagent 三类来源；空结果内联清理逻辑（不依赖 debounced 回调）；非空走 getPreservedSelection 保选中。'''),
    (505, 'after', r'''索引预热 useEffect。两个细节：① NODE_ENV=test 时跳过——REPL 挂载测试会对 CI 工作区（Windows runner 上 27 万+ 文件）起 git ls-files，后台构建还会活过测试泄漏进同分片后续测试；订阅者照常注册，直接触发刷新的测试不受影响。② 行 495 的 `"production" !== 'test'` 是恒假条件——构建期的环境变量替换把变量名烤成了字面量（同类事故在 services 层与 AgentTool/UI.tsx 各有一处），意图书载测试分支实际永不执行，靠的正是恒假。'''),
    (511, 'after', r'''50ms 防抖的选取依据写在注释里：刚好压过 macOS 默认连按间隔（~33ms），长按删除/退格合并成一次搜索；索引 27 万文件的搜索本身 ~8-15ms。'''),
    (529, 'after', r'''slack 频道 150ms 防抖（MCP 往返慢）；首个 # 之后同首词段的后续击键走同步缓存。'''),
    (887, 'after', r'''updateSuggestions 是整条补全优先级链的编排，顺序即优先级：中段 slash 命令（ghost text 优先，清下拉）→ bash 历史 ghost text → @队友/subagent（先于 @文件，防冲突；bash 模式跳过）→ #slack 频道 → /add-dir 目录补全 → /resume 自定义标题 → slash 命令列表 → @文件/路径补全 → shell 补全。每一类命中即 return，后面的不看。依赖数组刻意用 suggestionsRef 而非 suggestions——选中项变化不该重建回调。'''),
    (908, 'after', r'''input 变化 effect 的两个防抖修复：① dismissedForInputRef——用户按 Esc 撤了补全，同样的输入不再触发；② prevInputRef 检测真实文本变化，变化时清 latestSearchTokenRef——修「打 @readme.md、清空、重打 @readme.md 无建议」（同一 token 会被当成陈旧查询丢弃）。刻意不依赖 cursorOffset：光标移动不重取。'''),
    (935, 'after', r'''handleTab 的 ghost text 分支：bash 模式用历史全量命令替换输入；prompt 模式只替换中段那个命令词（保留前后文）。'''),
    (1133, 'after', r'''handleTab 的应用分支：七类补全各自的替换语义——command 补全不执行（Tab 只填）；custom-title 直接构造 /resume <sessionId>；directory 分命令上下文（只换参数部分，目录加 / 后继续下钻）与通用路径（@ 前缀替换整 token）；file 有公共前缀渐进补全（比已输入长才替换，不清列表让用户继续）；agent/slack 走触发替换；shell 单条建议直接应用。无建议时非空输入触发 bash shell 补全或文件补全。'''),
    (1225, 'after', r'''handleEnter 与 handleTab 的关键差别：command 补全**执行**（Enter 提交）；custom-title 直接 onSubmit；directory 在命令上下文（/add-dir）只清不应用——Enter 的语义是提交命令而不是选目录。'''),
    (1263, 'after', r'''四个 autocomplete 命令（accept/dismiss/previous/next）走 keybinding 系统而不是散落的 if-else——与全局键位表统一管理。'''),
    (1269, 'after', r'''overlay 注册顺序是要害：autocomplete 注册为 overlay，ESC 先撤补全再走取消任务——否则用户想关补全却把整个请求取消了。'''),
    (1279, 'after', r'''modal overlay（DiffDialog 等）激活时禁用补全键位——ESC 要让给覆盖层，补全让位。'''),
    (1362, 'after', r'''handleKeyDown 的遗留键盘路径（键位化迁移的残余）：右箭头接受 AppState 里的 prompt suggestion（空输入时才有效）；Tab 无补全时兜底（接受 suggestion 或提示 thinking toggle 快捷键）；Ctrl-N/P 上下移动（避开进行中的 chord 序列）；Enter 应用选中（Shift/Meta+Enter 是换行，不抢）。'''),
    (1374, 'after', r'''useInput 是向后兼容桥：PromptInput 还没把 handleKeyDown 接到 <Box onKeyDown>，这里用 useInput 订阅并把 InputEvent 适配成 KeyboardEvent，didStopImmediatePropagation 双向传递。TODO(onKeyDown-migration) 标记了迁移后删除点。'''),
    (1384, 'after', r'''返回六件套 + handleKeyDown。inlineGhostText 出口的是 effectiveGhostText（prompt 同步 / bash 异步的合并结果）。'''),
]
